"""
Verilog module to calculate the number of transitions in a 10-bit input data.
The transitions are counted in a single clock cycle when the Load signal is asserted.
"""

# Verilog code starts here
verilog_code = """
module Transition_Calculator(clk, load, clear, data, count);
    input clk, load, clear;
    input [9:0] data;
    output reg [4:0] count;

    // Internal variable to accumulate the number of transitions
    reg [4:0] transitions;

    always @(posedge clk or negedge clear) begin
        if (!clear) begin
            // Asynchronous clear - reset the count and transitions variables
            count <= 5'b0;
            transitions <= 5'b0;
        end else if (load) begin
            // Initialize the transitions counter
            transitions = 5'b0;
            // Calculate the number of transitions
            integer i;
            for (i = 0; i < 9; i = i + 1) begin
                if (data[i] != data[i+1]) begin
                    transitions = transitions + 1; // Use blocking assignment for calculation
                end
            end
            // Assign the calculated number of transitions to the output count
            count <= transitions;
        end
    end
endmodule
"""
